-- Passage rg5-connections-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('868b527a-f618-53d1-bfdf-0fd18d48fc8a', 'rg5-connections-p06', (select id from public.skills where slug = 'read-g5-connections'), null,
        '3-5', $q$The Conductor and the Orchestra$q$, $q$A school orchestra may have forty musicians, all playing different parts. Violins, cellos, flutes, trumpets, and drums each have their own music. Yet the whole group must sound like one piece. The person who holds it together is the conductor.

The conductor stands on a small platform in front of the orchestra. With a thin stick, the conductor shows the beat. Every musician watches the stick, so all of them play at the same speed. Without a shared beat, the sections would soon drift apart.

The conductor also shapes how loudly each section plays. A raised hand might ask the trumpets to play louder. A palm held low might quiet the drums so the flutes can be heard. In this way, the conductor balances the sections.

The musicians help the conductor too. During rehearsals, Mr. Dmitri Volkov, the conductor at Lakeview School, listens closely as each section practices. When the cellos told him one part was too fast to play cleanly, he slowed it down. The music sounded better for everyone.

By concert night, the conductor and the musicians have learned to work as a team. The audience hears one smooth piece of music, built from forty different parts.$q$, 'draft')
