-- Passage rg5-connections-p07
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('dc9c3009-8bec-5c9a-a029-624619b4617c', 'rg5-connections-p07', (select id from public.skills where slug = 'read-g5-connections'), null,
        '3-5', $q$Traffic Lights That Pay Attention$q$, $q$At a busy crossroads, traffic lights decide who goes and who waits. Older signals ran on a simple timer. Each direction got a green light for the same number of seconds, even if no cars were waiting. Drivers sometimes sat at an empty intersection, staring at a red light.

Many towns now use signals that respond to traffic. Sensors are placed in the road or on poles near the intersection. A sensor can tell when a car is waiting and how long a line of cars has grown. It sends this information to a small computer in a metal box beside the road.

The computer uses the information to change the lights. If cars are lined up on Main Street but no one is waiting on Oak Avenue, the computer keeps Main Street green longer. When a car pulls up on Oak Avenue, the computer gives that direction a turn.

Signals along the same road can also work together. When one light turns green, the next one down the road turns green a few seconds later. Cars moving at the speed limit can pass through several green lights in a row. This is sometimes called a green wave.

The town of Riverton added these signals last year. Traffic engineer Priya Natarajan reported that drivers now spend less time stopped. Because cars sit still with their engines running less often, they also burn less fuel.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
